function validate([wordsDict, word1, word2]) {
  if (wordsDict.length < 2 || wordsDict.length > 30000) return 'wordsDict needs 2 to 30000 words.';
  const word = /^[a-z]{1,10}$/;
  if (!wordsDict.every(w => word.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  if (word1 === word2) return 'word1 and word2 must be different.';
  if (!wordsDict.includes(word1) || !wordsDict.includes(word2)) return 'word1 and word2 must both occur in wordsDict.';
  return null;
}

