function shortestDistance(wordsDict, word1, word2) {
  let index1 = -1;
  let index2 = -1;
  let best = wordsDict.length;

  for (let i = 0; i < wordsDict.length; i++) {
    const word = wordsDict[i];
    if (word === word1) {
      index1 = i;
    }
    if (word === word2) {
      index2 = i;
    }
    if (index1 !== -1 && index2 !== -1) {
      best = Math.min(best, Math.abs(index1 - index2));
    }
  }
  return best;
}

brute:
function shortestDistance(wordsDict, word1, word2) {
  const first = [], second = [];
  wordsDict.forEach((w, i) => { if (w === word1) first.push(i); if (w === word2) second.push(i); });
  let best = Infinity;
  for (const a of first) for (const b of second) best = Math.min(best, Math.abs(a - b));
  return best;
}

