function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const vocab = size === 'large' ? ['code', 'make', 'test', 'run', 'debug', 'ship', 'read', 'write', 'think', 'plan', 'sleep', 'repeat'] : ['a', 'b', 'c', 'ab'];
  const n = size === 'large' ? 2000 : int(2, 10);
  const kinds = int(2, vocab.length);
  const words = Array.from({ length: n }, () => vocab[int(0, kinds - 1)]);
  const first = int(0, kinds - 1);
  let second = int(0, kinds - 2);
  if (second >= first) second++;
  // Both words must appear, so place each one at a different random position.
  const at1 = int(0, n - 1);
  let at2 = int(0, n - 2);
  if (at2 >= at1) at2++;
  words[at1] = vocab[first];
  words[at2] = vocab[second];
  return [words, vocab[first], vocab[second]];
}
